 19	/// One case's run.
 20	#[derive(Clone, Debug)]
 21	pub struct CaseRun {
 22	    pub id: String,
 23	    pub family: String,
 24	    /// `selected`, `refused`, `unresolved` or `source_refused`.
 25	    pub outcome: String,
 26	    pub selected_precision: Option<u32>,
 27	    pub tally: Tally,
 28	    /// Every failure, with its reason (a failure on a covered row is a stop).
 29	    pub failures: Vec<String>,
 30	    /// The not-covered keys the floor check found, in row order.
 31	    pub not_covered: Vec<String>,
 32	    /// Not-covered rows whose published row is not `absolute_verified` or
 33	    /// unpublishable (plan §7.2).
 34	    pub class_mismatches: Vec<String>,
 35	    /// Not-covered rows whose published row is `input_derived`: a displacement
 36	    /// at a restrained DOF, published as its exact prescription (D1 §4.1.6.1
 37	    /// rule 2a). Listed apart from the mismatches (A1 finding for ROOT).
 38	    pub input_derived_not_covered: Vec<String>,
 39	    pub controls: ControlTally,
 40	    /// The deterministic per-case record (plan §12).
 41	    pub record: Value,
 42	    /// The published rows, for the invariance checks.
 43	    pub published: BTreeMap<QuantityId, PublishedRow>,
 44	}
 45	
 46	/// The discrimination check of a case's value controls, against its reference
 47	/// rows (plan §8). Outcome controls are decided by `run_case`.
 48	pub fn value_controls(case: &Case) -> ControlTally {
 49	    let rows: BTreeMap<&str, &crate::cases::Row> =
 50	        case.rows.iter().map(|r| (r.key.as_str(), r)).collect();
 51	    let mut t = ControlTally::default();
 52	    for c in &case.controls {
 53	        let ControlKind::Value(values) = &c.kind else {
 54	            continue;
 55	        };
 56	        let fails = values.iter().any(|(key, v)| {
 57	            let row = rows
 58	                .get(key.as_str())
 59	                .unwrap_or_else(|| panic!("{}: control {} names {key}", case.id, c.id));
 60	            let exp = Exact::parse_decimal(&row.expected).unwrap();
 61	            let scale = Exact::parse_decimal(case.scale_of(row)).unwrap();
 62	            // A control's value (a magnitude too) is compared as a value.
 63	            let obs = Exact::parse_decimal(v).unwrap();
 64	            !exact::predicate(&obs, &exp, &scale)
 65	        });
 66	        let name = format!("{}:{}", case.id, c.id);
 67	        match (c.discriminates, fails) {
 68	            (true, true) => t.discriminated += 1,
 69	            (true, false) => t.undiscriminated.push(name),
 70	            (false, false) => t.non_discriminating += 1,
 71	            (false, true) => {
 72	                t.non_discriminating += 1;
 73	                t.unexpectedly_failing.push(name);
 74	            }
 75	        }
 76	    }
 77	    t
 78	}
 79	
 80	fn value_of(rows: &BTreeMap<QuantityId, PublishedRow>, id: QuantityId) -> Result<f64, String> {
 81	    match rows.get(&id).map(|r| r.value) {
 82	        Some(Binary64Outcome::Normal(v)) => Ok(v),
 83	        Some(Binary64Outcome::Subnormal { value, .. }) => Ok(value),
 84	        Some(Binary64Outcome::Underflow { negative }) => Ok(if negative { -0.0 } else { 0.0 }),
 85	        Some(Binary64Outcome::Overflow { .. }) => Err(format!("{id:?} overflowed")),
 86	        None => Err(format!("{id:?} not published")),
 87	    }
 88	}
