 98	/// The published rows a target is formed from.
 99	fn sources(target: Target) -> Vec<QuantityId> {
100	    match target {
101	        Target::Displacement(d) => vec![QuantityId::Displacement(d)],
102	        Target::Reaction(d) => vec![QuantityId::Reaction(d)],
103	        Target::Spring { id, component } => vec![QuantityId::SpringAction {
104	            spring: id,
105	            component,
106	        }],
107	        Target::DirectionalSpring { id, component } => {
108	            vec![QuantityId::DirectionalSpringAction {
109	                spring: id,
110	                component,
111	            }]
112	        }
113	        Target::StructuralZero => vec![],
114	        Target::Axial(m) | Target::Extension(m) => vec![end(m, true, Component::Ux)],
115	        Target::Torque(m) | Target::Twist(m) => vec![end(m, true, Component::Rx)],
116	        Target::BendingEnd { member, j_end } => vec![
117	            end(member, j_end, Component::Ry),
118	            end(member, j_end, Component::Rz),
119	        ],
120	        Target::BendingStation(s) => vec![
121	            QuantityId::StationAction {
122	                station: s,
123	                component: Component::Ry,
124	            },
125	            QuantityId::StationAction {
126	                station: s,
127	                component: Component::Rz,
128	            },
129	        ],
130	    }
131	}
