133	/// k_t and k_a of a member (DESIGN.md §4.10, with C1's pre-scaling).
134	pub fn member_coefficients(model: &Model, member: u32) -> (f64, f64) {
135	    let m = model.members.iter().find(|m| m.id == member).unwrap();
136	    let l = floor::member_length(
137	        model.nodes[m.node_i as usize],
138	        model.nodes[m.node_j as usize],
139	    );
140	    (
141	        floor::coefficient(m.shear_modulus, m.torsion_constant, l),
142	        floor::coefficient(m.elastic_modulus, m.area, l),
143	    )
144	}
