190	/// Runs a case on given parts (the list-permutation checks pass permuted parts).
191	pub fn run_parts(case: &Case, model: &Model, parts: SourceParts) -> CaseRun {
192	    let mut failures = Vec::new();
193	    let mut tally = Tally::default();
194	    let mut controls = value_controls(case);
195	    let mut published = BTreeMap::new();
196	    let mut not_covered = Vec::new();
197	    let mut class_mismatches = Vec::new();
198	    let mut input_derived_not_covered = Vec::new();
199	    let source = match PrimitiveSource::new(parts) {
200	        Ok(s) => s,
201	        Err(e) => {
202	            // No kernel outcome: every row fails; for a mechanism the named
203	            // source refusal is recorded (C10).
204	            for row in &case.rows {
205	                tally.add(&Verdict::Fail(format!("source refused: {e:?}")));
206	                failures.push(format!("{}: {} source refused: {e:?}", case.id, row.key));
207	            }
208	            if !case.refuse {
209	                failures.push(format!("{}: source refused: {e:?}", case.id));
210	            }
211	            decide_outcome_controls(case, false, &mut controls);
212	            let record = records::source_refused_record(case, &format!("{e:?}"), &tally);
213	            return CaseRun {
214	                id: case.id.clone(),
215	                family: case.family.clone(),
216	                outcome: "source_refused".into(),
217	                selected_precision: None,
218	                tally,
219	                failures,
220	                not_covered,
221	                class_mismatches,
222	                input_derived_not_covered,
223	                controls,
224	                record,
225	                published,
226	            };
227	        }
228	    };
229	    let encoding = source.encoding();
230	    if sha256_hex(&encoding) != case.k4src_sha256 {
231	        failures.push(format!(
232	            "{}: K4SRC sha256 differs from the generator's --model path",
233	            case.id
234	        ));
235	    }
236	    let mut meter = InvocationMeter::new(u64::MAX);
237	    let outcome = solve_case(source, CaseLimit::new(u64::MAX), &mut meter);
238	    let (label, selected_precision) = match &outcome {
239	        CaseOutcome::Selected(s) => ("selected", Some(s.selected_precision())),
240	        CaseOutcome::Refused { .. } => ("refused", None),
241	        CaseOutcome::Unresolved { .. } => ("unresolved", None),
242	    };
243	    if meter.exhausted() {
244	        failures.push(format!("{}: the invocation meter was exhausted", case.id));
245	    }
246	    let selected = matches!(outcome, CaseOutcome::Selected(_));
247	    decide_outcome_controls(case, selected, &mut controls);
248	    // ROOT's ruling on I17's A1 stop: a listed case must end unresolved with
249	    // no rows; leaving the list is a failure, and so is joining it.
250	    let listed = crate::cases::expected_unresolved().contains(&case.id);
251	    if listed && !matches!(outcome, CaseOutcome::Unresolved { .. }) {
252	        failures.push(format!(
253	            "{}: on the expected-unresolved list, but {}",
254	            case.id,
255	            records::outcome_text(&outcome)
256	        ));
257	    }
258	    if case.refuse {
259	        if let CaseOutcome::Selected(s) = &outcome {
260	            failures.push(format!(
261	                "{}: a mechanism was published ({} rows)",
262	                case.id,
263	                s.publish().rows.len()
264	            ));
265	        }
266	    } else if let CaseOutcome::Selected(s) = &outcome {
267	        for r in &s.publish().rows {
268	            published.insert(r.id, r.clone());
269	        }
270	        let bodies = model.bodies();
271	        if bodies.iter().any(|&b| b != 0) {
272	            failures.push(format!("{}: more than one body", case.id));
273	        }
274	        let scales = floor::scales(case, model);
275	        for row in &case.rows {
276	            let exp = Exact::parse_decimal(&row.expected).unwrap();
277	            let scale = Exact::parse_decimal(case.scale_of(row)).unwrap();
278	            let covered = exact::covered(&exp, &scale, floor::row_scale(row, &scales));
279	            let verdict = match model.resolve(&row.key) {
280	                Ok(target) => {
281	                    let v = judge(&observe(target, &published, model), &exp, &scale, covered);
282	                    if !covered {
283	                        not_covered.push(row.key.clone());
284	                        for id in sources(target) {
285	                            let restrained = matches!(id, QuantityId::Displacement(d)
286	                                if model.constraints.contains(&(d.node, d.component.index())));
287	                            match published.get(&id).map(|r| &r.class) {
288	                                Some(RowClass::AbsoluteVerified { .. })
289	                                | Some(RowClass::Unpublishable) => {}
290	                                Some(RowClass::InputDerived) if restrained => {
291	                                    input_derived_not_covered
292	                                        .push(format!("{}:{}", case.id, row.key))
293	                                }
294	                                other => class_mismatches.push(format!(
295	                                    "{}: {} ({id:?} is {other:?})",
296	                                    case.id, row.key
297	                                )),
298	                            }
299	                        }
300	                    }
301	                    v
302	                }
303	                Err(e) => Verdict::Fail(e),
304	            };
305	            if let Verdict::Fail(why) = &verdict {
306	                failures.push(format!("{}: {} ({}) {why}", case.id, row.key, row.expected));
307	            }
308	            tally.add(&verdict);
309	        }
310	    } else if listed && matches!(outcome, CaseOutcome::Unresolved { .. }) {
311	        for _row in &case.rows {
312	            tally.add(&Verdict::ExpectedUnresolved);
313	        }
314	    } else {
315	        for _row in &case.rows {
316	            tally.add(&Verdict::Fail(format!("case {label}")));
317	        }
318	        failures.push(format!(
319	            "{}: not selected: {}",
320	            case.id,
321	            records::outcome_text(&outcome)
322	        ));
323	    }
324	    let record = records::case_record(case, &outcome, &tally, &meter);
325	    CaseRun {
326	        id: case.id.clone(),
327	        family: case.family.clone(),
328	        outcome: label.into(),
329	        selected_precision,
330	        tally,
331	        failures,
332	        not_covered,
333	        class_mismatches,
334	        input_derived_not_covered,
335	        controls,
336	        record,
337	        published,
338	    }
339	}
