341	/// Outcome controls (plan §8): on a mechanism, each describes publishing a
342	/// solution, so the refusal discriminates it; on a stable model (the RF-MECH
343	/// companion), NC-FALSE-MECHANISM is a refusal, so the selection does.
344	fn decide_outcome_controls(case: &Case, selected: bool, t: &mut ControlTally) {
345	    for c in &case.controls {
346	        if let ControlKind::Outcome(_) = c.kind {
347	            let discriminated = if case.refuse { !selected } else { selected };
348	            match (c.discriminates, discriminated) {
349	                (true, true) => t.discriminated += 1,
350	                (true, false) => t.undiscriminated.push(format!("{}:{}", case.id, c.id)),
351	                (false, _) => t.non_discriminating += 1,
352	            }
353	        }
354	    }
355	}
