  1	//! The zero-scale floor check (T3 D1 §4.10, V1-S8, F2; plan §7).
  2	//!
  3	//! S\* per kind is formed from the case's reference values by D1 §4.1.6.1
  4	//! items 4–6, in binary64 and in the stated order: S(kind) is the largest
  5	//! |fl(exp)| of the kind (R1's class without `@region`), L_b is the body's
  6	//! extent from the adapted node coordinates, and the four kinds are coupled.
  7	//! Twist and extension are variant F: S\*_tw(m) = fl(mo/k_t) and
  8	//! S\*_ext(m) = fl(fo/k_a), with k_t and k_a as §4.10 forms them (C1 below).
  9	//! A comparison is covered iff max(|exp|, scale) ≥ R·S\*, R = 2^-34, decided
 10	//! exactly (`exact::covered`).
 11	use crate::cases::{Case, Model, Row};
 12	use std::collections::BTreeMap;
 13	
 14	/// R = 2^-34 (D1 §4.1.6, bits `0x3DD0000000000000`).
 15	pub const R_BITS: u64 = 0x3DD0_0000_0000_0000;
 16	
 17	pub fn r() -> f64 {
 18	    f64::from_bits(R_BITS)
 19	}
 20	
 21	fn is_normal(x: f64) -> bool {
 22	    x.is_normal()
 23	}
 24	
 25	/// FK's element length: `norm(subtract(xj, xi))` = `dot(v, v).sqrt()`, the
 26	/// products and sums left to right (`FK/lib.rs` `norm`, `dot`).
 27	pub fn member_length(xi: [f64; 3], xj: [f64; 3]) -> f64 {
 28	    let v = [xj[0] - xi[0], xj[1] - xi[1], xj[2] - xi[2]];
 29	    (v[0] * v[0] + v[1] * v[1] + v[2] * v[2]).sqrt()
 30	}
 31	
 32	/// §4.10's k = fl(fl(a·b)/L), where both intermediates are normal binary64
 33	/// numbers; None where the design's formula is not defined.
 34	pub fn design_coefficient(a: f64, b: f64, length: f64) -> Option<f64> {
 35	    let p = a * b;
 36	    let q = p / length;
 37	    (is_normal(p) && is_normal(q)).then_some(q)
 38	}
 39	
 40	/// 2^k for |k| ≤ 1022 (a normal power of two), from its bits.
 41	fn pow2(k: i32) -> f64 {
 42	    assert!((-1022..=1023).contains(&k));
 43	    f64::from_bits(((1023 + k) as u64) << 52)
 44	}
 45	
 46	/// x·2^k exactly for a normal result, in steps that keep every factor normal.
 47	fn scale2(mut x: f64, mut k: i32) -> f64 {
 48	    while k != 0 {
 49	        let s = k.clamp(-1000, 1000);
 50	        x *= pow2(s);
 51	        k -= s;
 52	    }
 53	    x
 54	}
 55	
 56	/// The binary exponent e with |x| in [2^e, 2^(e+1)) for a finite nonzero x.
 57	fn exponent(x: f64) -> i32 {
 58	    let bits = x.to_bits();
 59	    let biased = ((bits >> 52) & 0x7ff) as i32;
 60	    if biased == 0 {
 61	        let fraction = bits & ((1u64 << 52) - 1);
 62	        -1075 + (64 - fraction.leading_zeros() as i32)
 63	    } else {
 64	        biased - 1023
 65	    }
 66	}
 67	
 68	/// k = fl(fl(a·b)/L), ROOT's C1 ruling: where the design's formula is defined
 69	/// it is used as written; elsewhere (RF-RANGE LEF-small, where fl(G·J) rounds
 70	/// to 0, and LEF-large, where it overflows) the same two operations run on b
 71	/// pre-scaled by an exact power of two s, chosen so that a·b·2^s lies in
 72	/// [1, 4), and the quotient is unscaled exactly. For normal results a
 73	/// rounding commutes with an exact power-of-two scaling, so the two agree
 74	/// bit for bit wherever the design's intermediates are normal (tested on
 75	/// every member of every case).
 76	pub fn coefficient(a: f64, b: f64, length: f64) -> f64 {
 77	    if let Some(k) = design_coefficient(a, b, length) {
 78	        return k;
 79	    }
 80	    prescaled_coefficient(a, b, length)
 81	}
 82	
 83	/// The pre-scaled form alone (exposed for C1's equality test).
 84	pub fn prescaled_coefficient(a: f64, b: f64, length: f64) -> f64 {
 85	    let s = -(exponent(a) + exponent(b));
 86	    let q = (a * scale2(b, s)) / length;
 87	    scale2(q, -s)
 88	}
 89	
 90	/// S\* of one case: the four coupled kinds and, per member (by R1 name), the
 91	/// variant-F twist and extension scales.
 92	#[derive(Clone, Debug, PartialEq)]
 93	pub struct Scales {
 94	    /// translation, rotation, force, moment.
 95	    pub kinds: [f64; 4],
 96	    pub members: BTreeMap<String, (f64, f64)>,
 97	}
 98	
 99	fn kind_index(kind: &str) -> Option<usize> {
100	    ["translation", "rotation", "force", "moment"]
101	        .iter()
102	        .position(|k| *k == kind)
103	}
104	
105	/// D1 §4.1.6.1 item 5: L_b from the body's node coordinates.
106	pub fn body_extent(nodes: &[[f64; 3]]) -> f64 {
107	    let mut d = [0.0f64; 3];
108	    for (a, slot) in d.iter_mut().enumerate() {
109	        let hi = nodes.iter().map(|p| p[a]).fold(f64::NEG_INFINITY, f64::max);
110	        let lo = nodes.iter().map(|p| p[a]).fold(f64::INFINITY, f64::min);
111	        *slot = hi - lo;
112	    }
113	    (d[0] * d[0] + d[1] * d[1] + d[2] * d[2]).sqrt()
114	}
115	
116	/// D1 §4.1.6.1 item 6, in its order.
117	pub fn couple(s: [f64; 4], extent: f64) -> [f64; 4] {
118	    let [s_tr, s_ro, s_fo, s_mo] = s;
119	    if extent == 0.0 {
120	        return s;
121	    }
122	    [
123	        s_tr.max(extent * s_ro),
124	        s_ro.max(s_tr / extent),
125	        s_fo.max(s_mo / extent),
126	        s_mo.max(extent * s_fo),
127	    ]
128	}
129	
130	/// S(kind) = the largest |fl(exp)| of each kind over `values`.
131	pub fn maxima<'a>(values: impl Iterator<Item = (&'a str, &'a str)>) -> [f64; 4] {
132	    let mut s = [0.0f64; 4];
133	    for (kind, expected) in values {
134	        if let Some(k) = kind_index(kind) {
135	            let v: f64 = expected.parse().expect("decimal");
136	            s[k] = s[k].max(v.abs());
137	        }
138	    }
139	    s
140	}
141	
142	/// S\* from given maxima and the model (one body: asserted by the caller).
143	pub fn scales_from(maxima: [f64; 4], model: &Model) -> Scales {
144	    let kinds = couple(maxima, body_extent(&model.nodes));
145	    let (fo, mo) = (kinds[2], kinds[3]);
146	    let members = model
147	        .members
148	        .iter()
149	        .map(|m| {
150	            let l = member_length(
151	                model.nodes[m.node_i as usize],
152	                model.nodes[m.node_j as usize],
153	            );
154	            let kt = coefficient(m.shear_modulus, m.torsion_constant, l);
155	            let ka = coefficient(m.elastic_modulus, m.area, l);
156	            (m.name.clone(), (mo / kt, fo / ka))
157	        })
158	        .collect();
159	    Scales { kinds, members }
160	}
161	
162	/// S\* of a case from its reference rows.
163	pub fn scales(case: &Case, model: &Model) -> Scales {
164	    scales_from(
165	        maxima(case.rows.iter().map(|r| (r.kind(), r.expected.as_str()))),
166	        model,
167	    )
168	}
169	
170	/// The S\* a row is floored against.
171	pub fn row_scale(row: &Row, scales: &Scales) -> f64 {
172	    match kind_index(row.kind()) {
173	        Some(k) => scales.kinds[k],
174	        None => {
175	            let member = row.key.split_once('.').expect("tw.<m>/ext.<m>").1;
176	            let (tw, ext) = scales.members[member];
177	            match row.kind() {
178	                "twist" => tw,
179	                "extension" => ext,
180	                other => panic!("unknown class {other}"),
181	            }
182	        }
183	    }
184	}
185	
186	/// The keys of a case's rows below the floor, in row order.
187	pub fn not_covered(case: &Case, model: &Model, scales: &Scales) -> Vec<String> {
188	    let _ = model;
189	    case.rows
190	        .iter()
191	        .filter(|row| {
192	            let exp = crate::exact::Exact::parse_decimal(&row.expected).unwrap();
193	            let scale = crate::exact::Exact::parse_decimal(case.scale_of(row)).unwrap();
194	            !crate::exact::covered(&exp, &scale, row_scale(row, scales))
195	        })
196	        .map(|row| row.key.clone())
197	        .collect()
198	}

  1	//! The binary64 sparse gate's parity checks on RF-MECH and RF-LARGE (brief
  2	//! Scope 3; T3 D1 §4.8's parity protocol items 1–3; ROOT's C4 ruling: at up
  3	//! to 100 members; plan §5.3).
  4	//!
  5	//! The same adapted model is formed through FK's binary64 path (FK's
  6	//! `FrameElement`, global-axis springs, rigid DOFs, loads) in both modes, with
  7	//! the same M03 evidence: the stiffness contributions and the formation
  8	//! allowances in the form the structural adapter records them (as K1's
  9	//! pattern-path tests build them).
 10	//! - **Item 1:** every stored entry of the pattern assembly equals the dense
 11	//!   assembly's entry bit for bit, and every entry outside the pattern is +0.
 12	//! - **Item 2:** the M03 outcome class (Passed, Sensitive, or the refusal)
 13	//!   is the same in both modes.
 14	//! - **Item 3:** where both publish, max|u_sparse − u_dense| ≤ 1e-9·max|u_dense|
 15	//!   (the DEC-053 basis), decided exactly; asserted where both are Passed and
 16	//!   recorded otherwise.
 17	//!
 18	//! W1 is the lane's method; the binary64 values are not compared with R1 here.
 19	use crate::cases::Model;
 20	use crate::exact::Exact;
 21	use open_pipe_stress_frame_kernel::structural::{
 22	    assemble_sparse_stiffness, gamma, solve_structural_dense, transform_roundoff,
 23	    SparseAssemblyOptions, SparseStiffness, SparseStructuralSystem, SparseSymmetryEvidence,
 24	    StiffnessContribution, StructuralError, StructuralSolution, StructuralSystem, SymmetryEvidence,
 25	};
 26	use open_pipe_stress_frame_kernel::{
 27	    assemble_global_stiffness, element_dof_map, FrameElement, FrameNode, FrameSection,
 28	};
 29	use open_pipe_stress_sparse_direct::structural::solve_sparse_structural;
 30	use std::cmp::Ordering;
 31	use std::collections::BTreeMap;
 32	
 33	const BASIS: &str = "V-K parity: the structural adapter's formation allowances";
 34	
 35	/// A model in FK's binary64 terms.
 36	pub struct Binary64Model {
 37	    pub node_count: usize,
 38	    pub frames: Vec<FrameElement>,
 39	    pub springs: Vec<(usize, f64)>,
 40	    pub force: Vec<f64>,
 41	    pub free: Vec<usize>,
 42	    pub prescribed: Vec<(usize, f64)>,
 43	}
 44	
 45	pub fn binary64_model(model: &Model) -> Result<Binary64Model, String> {
 46	    let nodes: Vec<FrameNode> = model
 47	        .nodes
 48	        .iter()
 49	        .enumerate()
 50	        .map(|(k, p)| FrameNode::new(k, *p).map_err(|e| format!("{e:?}")))
 51	        .collect::<Result<_, _>>()?;
 52	    let frames = model
 53	        .members
 54	        .iter()
 55	        .map(|m| {
 56	            let section = FrameSection::new(
 57	                m.elastic_modulus,
 58	                m.shear_modulus,
 59	                m.area,
 60	                m.second_moment_y,
 61	                m.second_moment_z,
 62	                m.torsion_constant,
 63	            )
 64	            .map_err(|e| format!("{e:?}"))?;
 65	            FrameElement::new(
 66	                nodes[m.node_i as usize],
 67	                nodes[m.node_j as usize],
 68	                section,
 69	                m.y_reference,
 70	            )
 71	            .map_err(|e| format!("{e:?}"))
 72	        })
 73	        .collect::<Result<Vec<_>, _>>()?;
 74	    let mut springs = Vec::new();
 75	    for s in &model.springs {
 76	        match s.axis {
 77	            Some(a) => springs.push((s.node as usize * 6 + a, s.stiffness)),
 78	            None => return Err("a directional spring has no binary64 form".into()),
 79	        }
 80	    }
 81	    let n = model.nodes.len() * 6;
 82	    let mut force = vec![0.0; n];
 83	    for (node, c, v, _) in &model.loads {
 84	        force[*node as usize * 6 + c] += v;
 85	    }
 86	    let restrained: Vec<usize> = model
 87	        .constraints
 88	        .iter()
 89	        .map(|&(node, c)| node as usize * 6 + c)
 90	        .collect();
 91	    let free = (0..n).filter(|g| !restrained.contains(g)).collect();
 92	    let mut prescribed: Vec<(usize, f64)> = restrained.iter().map(|&g| (g, 0.0)).collect();
 93	    prescribed.sort_by_key(|p| p.0);
 94	    Ok(Binary64Model {
 95	        node_count: model.nodes.len(),
 96	        frames,
 97	        springs,
 98	        force,
 99	        free,
100	        prescribed,
101	    })
102	}
103	
104	/// Both triangles of every element's and spring's contribution, before
105	/// coalescence.
106	fn contributions(m: &Binary64Model) -> Vec<StiffnessContribution> {
107	    let mut out = Vec::new();
108	    for e in &m.frames {
109	        let k = e.global_stiffness().expect("formed");
110	        let map = element_dof_map(e.node_i.index, e.node_j.index);
111	        for i in 0..12 {
112	            for j in 0..12 {
113	                out.push(StiffnessContribution {
114	                    row: map[i],
115	                    col: map[j],
116	                    value: k[i][j],
117	                });
118	            }
119	        }
120	    }
121	    for &(dof, value) in &m.springs {
122	        out.push(StiffnessContribution {
123	            row: dof,
124	            col: dof,
125	            value,
126	        });
127	    }
128	    out
129	}
130	
131	/// The formation allowances and operation counts per (row, col), in the
132	/// structural adapter's form: each element's `transform_roundoff`, one count
133	/// per spring, and γ(scatter)·Σ|contributions|.
134	fn allowances(
135	    m: &Binary64Model,
136	    c: &[StiffnessContribution],
137	) -> BTreeMap<(usize, usize), (f64, usize)> {
138	    let mut out: BTreeMap<(usize, usize), (f64, usize)> = BTreeMap::new();
139	    for e in &m.frames {
140	        let t = e.orientation().expect("oriented").transformation_matrix();
141	        let evidence =
142	            transform_roundoff(&e.local_stiffness().expect("formed"), &t).expect("finite");
143	        let map = element_dof_map(e.node_i.index, e.node_j.index);
144	        for i in 0..12 {
145	            for j in 0..12 {
146	                let slot = out.entry((map[i], map[j])).or_default();
147	                slot.0 += evidence.absolute_roundoff[i][j];
148	                slot.1 += evidence.operation_counts[i][j] + 1;
149	            }
150	        }
151	    }
152	    for &(dof, _) in &m.springs {
153	        out.entry((dof, dof)).or_default().1 += 1;
154	    }
155	    let mut magnitude: BTreeMap<(usize, usize), (f64, usize)> = BTreeMap::new();
156	    for x in c {
157	        let slot = magnitude.entry((x.row, x.col)).or_default();
158	        slot.0 += x.value.abs();
159	        slot.1 += 1;
160	    }
161	    for (key, (mag, scatter)) in magnitude {
162	        out.entry(key).or_default().0 += gamma(scatter) * mag;
163	    }
164	    out
165	}
166	
167	/// The M03 outcome class of a result.
168	pub fn class(r: &Result<StructuralSolution, StructuralError>) -> String {
169	    match r {
170	        Ok(s) => format!("{:?}", s.report.quality),
171	        Err(StructuralError::InvalidInput(w)) => format!("InvalidInput({w})"),
172	        Err(StructuralError::Range(w)) => format!("Range({w})"),
173	        Err(StructuralError::Asymmetric { .. }) => "Asymmetric".into(),
174	        Err(StructuralError::NumericallyUnresolved { reason, .. }) => {
175	            format!("NumericallyUnresolved({reason})")
176	        }
177	        Err(StructuralError::NegativeEnergy { .. }) => "NegativeEnergy".into(),
178	        Err(StructuralError::Mechanism { .. }) => "Mechanism".into(),
179	    }
180	}
