182	#[derive(Clone, Debug)]
183	pub struct Parity {
184	    /// Item 1: None when the pattern and dense assemblies agree bit for bit
185	    /// (only where the dense mode runs).
186	    pub bitwise_k: Option<Option<String>>,
187	    pub sparse: String,
188	    pub dense: Option<String>,
189	    /// Item 3 where both modes publish: within the DEC-053 basis, and the
190	    /// ratio max|Δu|/(1e-9·max|u_dense|) for display.
191	    pub delta: Option<(bool, f64)>,
192	    pub both_passed: bool,
193	}
194	
195	fn max_abs(v: &[f64]) -> f64 {
196	    v.iter().fold(0.0f64, |m, x| m.max(x.abs()))
197	}
198	
199	/// Items 1–3 on one model; `dense` runs the dense mode too (≤ ~100 members).
200	pub fn parity(model: &Model, dense: bool) -> Result<Parity, String> {
201	    let m = binary64_model(model)?;
202	    let c = contributions(&m);
203	    let allow = allowances(&m, &c);
204	    let sparse_k: SparseStiffness = assemble_sparse_stiffness(
205	        m.node_count,
206	        &m.frames,
207	        &[],
208	        &[],
209	        &m.springs,
210	        &SparseAssemblyOptions::new(),
211	    )
212	    .map_err(|e| format!("{e:?}"))?;
213	    let n = m.node_count * 6;
214	    let pattern = sparse_k.pattern();
215	    let (mut s_round, mut s_count) = (Vec::new(), Vec::new());
216	    for row in 0..n {
217	        for e in pattern.row_range(row) {
218	            let (r, k) = allow
219	                .get(&(row, pattern.column(e)))
220	                .copied()
221	                .unwrap_or((0.0, 0));
222	            s_round.push(r);
223	            s_count.push(k);
224	        }
225	    }
226	    let ss = SparseStructuralSystem::new(
227	        &sparse_k,
228	        &m.force,
229	        &m.free,
230	        &m.prescribed,
231	        Some(&c),
232	        Some(SparseSymmetryEvidence {
233	            absolute_roundoff: &s_round,
234	            operation_counts: &s_count,
235	            basis: BASIS,
236	        }),
237	    );
238	    let sparse = solve_sparse_structural(&ss);
239	    let mut out = Parity {
240	        bitwise_k: None,
241	        sparse: class(&sparse),
242	        dense: None,
243	        delta: None,
244	        both_passed: false,
245	    };
246	    if !dense {
247	        return Ok(out);
248	    }
249	    let mut dense_k =
250	        assemble_global_stiffness(m.node_count, &m.frames).map_err(|e| format!("{e:?}"))?;
251	    for &(dof, v) in &m.springs {
252	        dense_k[dof][dof] += v;
253	    }
254	    let mut mismatch = None;
255	    'rows: for (row, dense_row) in dense_k.iter().enumerate() {
256	        for (col, &d) in dense_row.iter().enumerate() {
257	            let stored = pattern.find(row, col).map(|_| sparse_k.get(row, col));
258	            let ok = match stored {
259	                Some(v) => v.to_bits() == d.to_bits(),
260	                None => d.to_bits() == 0.0f64.to_bits(),
261	            };
262	            if !ok {
263	                mismatch = Some(format!("({row}, {col}): pattern {stored:?}, dense {d:e}"));
264	                break 'rows;
265	            }
266	        }
267	    }
268	    out.bitwise_k = Some(mismatch);
269	    let mut d_round = vec![vec![0.0; n]; n];
270	    let mut d_count = vec![vec![0usize; n]; n];
271	    for (&(i, j), &(r, k)) in &allow {
272	        d_round[i][j] = r;
273	        d_count[i][j] = k;
274	    }
275	    let ds = StructuralSystem {
276	        stiffness: &dense_k,
277	        force: &m.force,
278	        free_dofs: &m.free,
279	        prescribed: &m.prescribed,
280	        contributions: Some(&c),
281	        symmetry: Some(SymmetryEvidence {
282	            absolute_roundoff: &d_round,
283	            operation_counts: &d_count,
284	            basis: BASIS,
285	        }),

  1	//! The comparison and report engine (T3 D1 §4.10's table; plan §6.3).
  2	//!
  3	//! Each R1 row gets exactly one verdict: `pass`, `fail`, `not_covered` (with
  4	//! whether the predicate held, never a pass), `pass_absolute_range` (the
  5	//! expected value has no binary64 value; separately counted), or
  6	//! `structural_zero` (no published row by construction; R1's value must be
  7	//! exactly 0), or `expected_unresolved` (the row of a case on the committed
  8	//! expected-unresolved list, which ended honestly unresolved with no rows:
  9	//! ROOT's ruling on THIN-A and THIN-B; never a pass). The report shows
 10	//! passes, absolute-range passes and not-covered comparisons as three
 11	//! separate numbers, and the six tallies must add up to the rows compared.
 12	use crate::exact::{self, Exact};
 13	use std::fmt;
 14	
 15	/// What the kernel published for a row.
 16	#[derive(Clone, Debug, PartialEq)]
 17	pub enum Observed {
 18	    /// A binary64 value (an `Underflow` row is observed as its rounding, ±0).
 19	    Value(f64),
 20	    /// The two components of a bending magnitude.
 21	    Magnitude(f64, f64),
 22	    /// No row by construction (plan §4.2).
 23	    StructuralZero,
 24	    /// Nothing comparable was published (missing, or overflowed).
 25	    Unavailable(String),
 26	}
 27	
 28	#[derive(Clone, Debug, PartialEq)]
 29	pub enum Verdict {
 30	    Pass,
 31	    Fail(String),
 32	    NotCovered { predicate_held: bool },
 33	    PassAbsoluteRange,
 34	    StructuralZero,
 35	    ExpectedUnresolved,
 36	}
 37	
 38	fn holds(obs: &Observed, exp: &Exact, scale: &Exact) -> Option<bool> {
 39	    match obs {
 40	        Observed::Value(v) => Some(exact::predicate(&Exact::from_f64(*v), exp, scale)),
 41	        Observed::Magnitude(y, z) => Some(exact::magnitude_predicate(*y, *z, exp, scale)),
 42	        _ => None,
 43	    }
 44	}
 45	
 46	/// The verdict of one row: `covered` is the floor check's decision.
 47	pub fn judge(obs: &Observed, exp: &Exact, scale: &Exact, covered: bool) -> Verdict {
 48	    if *obs == Observed::StructuralZero {
 49	        return if exp.is_zero() {
 50	            Verdict::StructuralZero
 51	        } else {
 52	            Verdict::Fail("structural zero with a nonzero reference".into())
 53	        };
 54	    }
 55	    if !covered {
 56	        return Verdict::NotCovered {
 57	            predicate_held: holds(obs, exp, scale).unwrap_or(false),
 58	        };
 59	    }
 60	    match holds(obs, exp, scale) {
 61	        None => Verdict::Fail(match obs {
 62	            Observed::Unavailable(why) => why.clone(),
 63	            _ => unreachable!(),
 64	        }),
 65	        Some(true) if exact::outside_binary64(exp) => Verdict::PassAbsoluteRange,
 66	        Some(true) => Verdict::Pass,
 67	        Some(false) => Verdict::Fail("predicate".into()),
 68	    }
 69	}
 70	
 71	#[derive(Clone, Debug, Default, PartialEq, Eq)]
 72	pub struct Tally {
 73	    pub rows: usize,
 74	    pub pass: usize,
 75	    pub pass_absolute_range: usize,
 76	    pub not_covered: usize,
 77	    pub structural_zero: usize,
 78	    pub expected_unresolved: usize,
 79	    pub fail: usize,
 80	}
 81	
 82	impl Tally {
 83	    pub fn add(&mut self, v: &Verdict) {
 84	        self.rows += 1;
 85	        match v {
 86	            Verdict::Pass => self.pass += 1,
 87	            Verdict::PassAbsoluteRange => self.pass_absolute_range += 1,
 88	            Verdict::NotCovered { .. } => self.not_covered += 1,
 89	            Verdict::StructuralZero => self.structural_zero += 1,
 90	            Verdict::ExpectedUnresolved => self.expected_unresolved += 1,
 91	            Verdict::Fail(_) => self.fail += 1,
 92	        }
 93	    }
 94	
 95	    pub fn merge(&mut self, o: &Tally) {
 96	        self.rows += o.rows;
 97	        self.pass += o.pass;
 98	        self.pass_absolute_range += o.pass_absolute_range;
 99	        self.not_covered += o.not_covered;
100	        self.structural_zero += o.structural_zero;
101	        self.expected_unresolved += o.expected_unresolved;
102	        self.fail += o.fail;
103	    }
104	
105	    /// Every row has exactly one verdict.
106	    pub fn accounted(&self) -> bool {
107	        self.pass
108	            + self.pass_absolute_range
109	            + self.not_covered
110	            + self.structural_zero
111	            + self.expected_unresolved
112	            + self.fail
113	            == self.rows
114	    }
115	}
116	
117	impl fmt::Display for Tally {
118	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
119	        write!(
120	            f,
121	            "rows {}: passes {}, absolute-range passes {}, not covered {} | structural zeros {}, \
122	             expected unresolved {}, failures {}",
123	            self.rows,
124	            self.pass,
125	            self.pass_absolute_range,
126	            self.not_covered,
127	            self.structural_zero,
128	            self.expected_unresolved,
129	            self.fail
130	        )
131	    }
132	}
133	
134	/// The discrimination tally of a set of cases (plan §8).
135	#[derive(Clone, Debug, Default, PartialEq, Eq)]
136	pub struct ControlTally {
137	    /// Discriminating controls that fail the predicate (or, for outcome
138	    /// controls, whose defect the kernel's outcome excludes).
139	    pub discriminated: usize,
140	    /// R1's non-discriminating controls (reported, never dropped).
141	    pub non_discriminating: usize,
142	    /// Discriminating controls that pass: each blocks the gate.
143	    pub undiscriminated: Vec<String>,
144	    /// Non-discriminating controls that V-K finds failing anyway (a
145	    /// difference from R1's own analysis; listed).
146	    pub unexpectedly_failing: Vec<String>,
147	}
148	
149	impl ControlTally {
150	    pub fn merge(&mut self, o: &ControlTally) {
151	        self.discriminated += o.discriminated;
152	        self.non_discriminating += o.non_discriminating;
153	        self.undiscriminated
154	            .extend(o.undiscriminated.iter().cloned());
155	        self.unexpectedly_failing
156	            .extend(o.unexpectedly_failing.iter().cloned());
157	    }
158	}

54:macro_rules! json {
70:macro_rules! json_internal {
135:    // inserted into the given map variable.
148:        let _ = $object.insert(($($key)+).into(), $value);
159:        let _ = $object.insert(($($key)+).into(), $value);
257:        $crate::Value::Array($crate::__private::vec![])
261:        $crate::Value::Array($crate::json_internal!(@array [] $($tt)+))
265:        $crate::Value::Object($crate::Map::new())
270:            let mut object = $crate::Map::new();
279:        $crate::to_value(&$other).unwrap()
287:macro_rules! json_internal_vec {
295:macro_rules! json_unexpected {
301:macro_rules! json_expect_expr_comma {

    //
    // Must be invoked as: json_internal!(@object $map () ($($tt)*) ($($tt)*))
    //
    // We require two copies of the input tokens so that we can match on one
    // copy and trigger errors on the other copy.
    //////////////////////////////////////////////////////////////////////////

    // Done.
    (@object $object:ident () () ()) => {};

    // Insert the current entry followed by trailing comma.
    (@object $object:ident [$($key:tt)+] ($value:expr) , $($rest:tt)*) => {
        let _ = $object.insert(($($key)+).into(), $value);
        $crate::json_internal!(@object $object () ($($rest)*) ($($rest)*));
    };

    // Current entry followed by unexpected token.
    (@object $object:ident [$($key:tt)+] ($value:expr) $unexpected:tt $($rest:tt)*) => {
        $crate::json_unexpected!($unexpected);
    };

    // Insert the last entry without trailing comma.
    (@object $object:ident [$($key:tt)+] ($value:expr)) => {
        let _ = $object.insert(($($key)+).into(), $value);
    };

    // Next value is `null`.
    (@object $object:ident ($($key:tt)+) (: null $($rest:tt)*) $copy:tt) => {
        $crate::json_internal!(@object $object [$($key)+] ($crate::json_internal!(null)) $($rest)*);
    };

    ([]) => {
        $crate::Value::Array($crate::__private::vec![])
    };

    ([ $($tt:tt)+ ]) => {
        $crate::Value::Array($crate::json_internal!(@array [] $($tt)+))
    };

    ({}) => {
        $crate::Value::Object($crate::Map::new())
    };

    ({ $($tt:tt)+ }) => {
        $crate::Value::Object({
            let mut object = $crate::Map::new();
            $crate::json_internal!(@object object () ($($tt)+) ($($tt)+));
            object
        })
    };

    // Any Serialize type: numbers, strings, struct literals, variables etc.
    // Must be below every other rule.
    ($other:expr) => {
        $crate::to_value(&$other).unwrap()
    };
}

    #[inline]
    fn serialize<S>(&self, serializer: S) -> result::Result<S::Ok, S::Error>
    where
        S: ::serde::Serializer,
    {
        match self {
            Value::Null => serializer.serialize_unit(),
            Value::Bool(b) => serializer.serialize_bool(*b),
            Value::Number(n) => n.serialize(serializer),
            Value::String(s) => serializer.serialize_str(s),
            Value::Array(v) => v.serialize(serializer),
            #[cfg(any(feature = "std", feature = "alloc"))]
            Value::Object(m) => {
                use serde::ser::SerializeMap;
                let mut map = tri!(serializer.serialize_map(Some(m.len())));
                for (k, v) in m {
                    tri!(map.serialize_entry(k, v));
                }
                map.end()
            }
            #[cfg(not(any(feature = "std", feature = "alloc")))]
            Value::Object(_) => unreachable!(),
        }
    }
}

